// Seed keywords for research
const seedKeywords = ($env.SEO_SEED_KEYWORDS || 'marketing digital,automatisation marketing,agence marketing,publicite en ligne,social media marketing').split(',');

return { json: { seed_keywords: seedKeywords, site_url: $env.WEBSITE_URL || 'example.com' } };

const autocomplete1 = $('Google Autocomplete 1').item.json;
const autocomplete2 = $('Google Autocomplete 2').item.json;
const serpData = $('SERP Analysis').item.json;
const config = $('Configure Seed Keywords').item.json;

const suggestions1 = (autocomplete1.suggestions || []).map(s => s.value);
const suggestions2 = (autocomplete2.suggestions || []).map(s => s.value);

const relatedSearches = (serpData.related_searches || []).map(r => r.query);
const peopleAlsoAsk = (serpData.related_questions || []).map(q => q.question);

return {
  json: {
    seed_keywords: config.seed_keywords,
    site_url: config.site_url,
    autocomplete_suggestions: [...suggestions1, ...suggestions2],
    related_searches: relatedSearches,
    people_also_ask: peopleAlsoAsk,
    top_organic: (serpData.organic_results || []).slice(0, 5).map(r => ({ title: r.title, url: r.link })),
    ads_present: (serpData.ads || []).length > 0
  }
};

