const aiResponse = $input.item.json.message.content;
let keywords;
try { keywords = JSON.parse(aiResponse); } catch (e) { keywords = { error: 'Parse failed' }; }

// Save primary keywords to seo_tracking table
const keywordsToTrack = (keywords.primary_keywords || []).map(kw => ({
  keyword: kw.keyword,
  search_volume: kw.estimated_volume === 'high' ? 10000 : kw.estimated_volume === 'medium' ? 1000 : 100,
  difficulty: kw.estimated_difficulty,
  date: new Date().toISOString().split('T')[0]
}));

return {
  json: {
    report_type: 'keyword_research',
    generated_at: new Date().toISOString(),
    agent_id: 'seo-specialist',
    workflow_id: 'WF-SEO-KEYWORDS',
    keywords,
    keywords_to_track: keywordsToTrack
  }
};

